template.css:
.start-btn {
  background: linear-gradient(135deg, #00ff88, #00cc66);
  color: #000;
  border: 2px solid #00ff88;
  border-radius: 8px;
  padding: 12px 24px;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.2s;
}
.start-btn:hover {
  box-shadow: 0 0 20px rgba(0, 255, 136, 0.5);
  transform: scale(1.05);
}
.start-btn:active {
  transform: scale(0.95);
}
.start-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

template.js:
function initStartButton(element, config) {
  element.addEventListener('click', () => {
    if (config.confirmRequired) {
      if (confirm(`Start ${config.equipmentName}?`)) {
        writeTag(config.writeTag, config.writeValue);
      }
    } else {
      writeTag(config.writeTag, config.writeValue);
    }
  });
}
